44:  {place:'FUNCHAL · PORTUGAL',year:'1997',club:'MADEIRA',title:'The island boy',tag:'CHAPTER 01 · THE BEGINNING',speaker:'DOLORES',text:'The Atlantic wind rattles the windows. You are twelve, a ball at your feet, and a decision to make: leave Madeira for Lisbon, or keep the island close a little longer.',choices:[['Take the Sporting academy trial. The dream is bigger than home.','craft',5,'BOLD'],['Stay one more season. Family comes before the fast track.','loyalty',7,'ROOTED']]},
45:  {place:'ALCochete · LISBON',year:'2002',club:'SPORTING CP',title:'A new kind of player',tag:'CHAPTER 02 · THE ACADEMY',speaker:'YOUTH COACH',text:'At Sporting, your feet are quick and your stepovers quicker. The coaches want a team player. You want to be unforgettable. A visiting scout watches from the touchline.',choices:[['Work on the tricks after training. Let the football do the talking.','craft',8,'FOOTBALL FIRST'],['Ask for the number 7 shirt. Make them remember your name.','aura',7,'MAKE A STATEMENT']]},
46:  {place:'OLD TRAFFORD · MANCHESTER',year:'2003',club:'MANCHESTER UNITED',title:'The number seven',tag:'CHAPTER 03 · FIRST FLIGHT',speaker:'SIR ALEX',text:'A packed Old Trafford. Sir Alex has handed you the famous shirt. The crowd is waiting for a show; the veterans are waiting to see if you can deliver when it matters.',choices:[['Play the simple pass, then attack the space. Earn their trust.','craft',6,'TEAM FIRST'],['Take on the fullback. This is your moment to announce yourself.','aura',6,'FEARLESS']] ,match:true},
47:  {place:'MOSCOW · RUSSIA',year:'2008',club:'MANCHESTER UNITED',title:'Rain on the big night',tag:'CHAPTER 04 · THE FINAL',speaker:'RYAN GIGGS',text:'Champions League final. The pitch shines with rain. Teammates look to you, but the penalty spot feels a mile away. One kick can make a legend—or leave a scar.',choices:[['Ask to take the first penalty. Set the tone for everyone.','legacy',7,'LEAD THE WAY'],['Save your energy. Trust the captain and be ready for the rebound.','loyalty',5,'TRUST THE TEAM']] ,match:true},
48:  {place:'SANTIAGO BERNABÉU · MADRID',year:'2009',club:'REAL MADRID',title:'A galaxy of stars',tag:'CHAPTER 05 · THE NEW GALÁCTICO',speaker:'KARIM BENZEMA',text:'A new city, a world-record welcome, and a dressing room full of stars. Karim grins: “We can win everything. But who takes the last shot?” The Bernabéu holds its breath.',choices:[['Build a partnership. Greatness is even better shared.','loyalty',7,'PARTNERS IN CRIME'],['Demand the ball. You came here to be the difference.','aura',8,'THE MAIN MAN']]},
49:  {place:'LISBON · PORTUGAL',year:'2016',club:'PORTUGAL',title:'For the whole country',tag:'CHAPTER 06 · THE NATIONAL DREAM',speaker:'PEPE',text:'Your knee is hurt. The Euro final is slipping away. From the sideline, you can still lead Portugal—your voice, your belief, your teammates. The country is watching.',choices:[['Stay beside the team. Be their voice from the touchline.','loyalty',9,'CAPTAIN ALWAYS'],['Try to return. You refuse to leave this fight.','legacy',8,'NEVER GIVE IN']] ,match:true},
50:  {place:'CARDIFF · WALES',year:'2017',club:'REAL MADRID',title:'Three in a row?',tag:'CHAPTER 07 · A DYNASTY',speaker:'ZINÉDINE ZIDANE',text:'The final is level. Zidane catches your eye: one more burst, one more leap. Your body says slow down. Your ambition says the moment belongs to you.',choices:[['Trust your movement. Attack the space behind the defense.','craft',7,'THE PERFECT RUN'],['Call for the ball and take responsibility yourself.','legacy',8,'MAKE HISTORY']] ,match:true},
51:  {place:'RIYADH · SAUDI ARABIA',year:'2023',club:'AL NASSR',title:'The next chapter',tag:'CHAPTER 08 · WHAT COMES NEXT',speaker:'YOUNG FAN',text:'A new league, a new generation, a familiar number seven in the stands. A young fan asks what comes after breaking every record. The answer is yours to write.',choices:[['Build something lasting. Help the next generation rise.','loyalty',8,'PASS IT ON'],['One more record. One more impossible night.','legacy',9,'EXTRA TIME']]}
52: ];
53: const labels={craft:'Technique',aura:'Stardom',loyalty:'Team spirit',legacy:'Legacy'};
54: const initial={chapter:0,phase:'intro',stats:{craft:28,aura:24,loyalty:35,legacy:18},goals:0,decisions:[],shot:0,shotGoals:0,saved:false};
55: let game=load();let sound=false;let selected=0;let needle=0,dir=1,anim=null;
56: const $=s=>document.querySelector(s);
57: function load(){try{const x=JSON.parse(localStorage.getItem('extra-time-save'));return x&&x.chapter!==undefined?x:structuredClone(initial)}catch{return structuredClone(initial)}}
58: function save(){game.saved=true;localStorage.setItem('extra-time-save',JSON.stringify(game));$('#save-state').textContent='AUTOSAVED';}
59: function clamp(n){return Math.max(0,Math.min(100,n))}
60: function render(){updateSide();const c=chapters[game.chapter];$('#season-label').textContent=game.phase==='ending'?'CAREER COMPLETE':`SEASON ${c?.year||'—'} · ${c?.club||'THE END'}`;$('#save-state').textContent=game.saved?'AUTOSAVED':'NEW SAVE';
61:  if(game.phase==='intro'){intro();drawScene(0);$('#scene-eyebrow').textContent='A STORY THAT’S YOURS';$('#scene-title').textContent='One more chance.';$('#scene-number').textContent='00 / 08';$('#location').textContent='FUNCHAL · PORTUGAL';$('#year').textContent='1997';return}
62:  if(game.phase==='ending'){ending();drawScene(7);$('#scene-eyebrow').textContent='CHAPTER 08 · YOUR LEGACY';$('#scene-title').textContent='The final whistle?';$('#scene-number').textContent='08 / 08';$('#location').textContent='RIYADH · SAUDI ARABIA';$('#year').textContent='2023';return}
63:  $('#scene-eyebrow').textContent=c.tag;$('#scene-title').textContent=c.title;$('#scene-number').textContent=`${String(game.chapter+1).padStart(2,'0')} / 08`;$('#location').textContent=c.place;$('#year').textContent=c.year;drawScene(game.chapter);
64:  if(game.phase==='choice')choiceScreen(c);else if(game.phase==='match')matchScreen(c);
65: }
66: function intro(){ $('#content').innerHTML=`<div class="dialogue"><div class="portrait">CR7</div><div><div class="speaker">THE STORYTELLER</div><div class="dialogue-text">Lisbon to Manchester. Madrid to Riyadh. The career is real. The choices—and the what-ifs—are yours. Shape the player, chase the moments, write your own ending.</div></div></div><div class="choices"><button class="choice" id="start"><span class="choice-key">↵</span><span class="choice-copy">START CAREER <span class="choice-hint">8 CHAPTERS · YOUR LEGACY</span></span></button></div>`;$('#start').onclick=()=>{game=structuredClone(initial);game.phase='choice';game.saved=false;save();render()}}
67: function choiceScreen(c){$('#content').innerHTML=`<div class="dialogue"><div class="portrait">${c.speaker.slice(0,2)}</div><div><div class="speaker">${c.speaker}</div><div class="dialogue-text">${c.text}</div></div></div><div class="choices">${c.choices.map((x,i)=>`<button class="choice" data-choice="${i}"><span class="choice-key">${i+1}</span><span class="choice-copy">${x[0]} <span class="choice-hint">${x[3]}</span></span></button>`).join('')}</div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(+b.dataset.choice))}
68: function choose(i){const c=chapters[game.chapter],opt=c.choices[i];game.stats[opt[1]]=clamp(game.stats[opt[1]]+opt[2]);game.decisions.push({chapter:game.chapter,choice:i});if(c.match){game.phase='match';game.shot=0;game.shotGoals=0;needle=0;dir=1}else next();save();render()}
69: function next(){game.chapter++;if(game.chapter>=chapters.length)game.phase='ending';else game.phase='choice'}
70: function matchScreen(c){$('#content').innerHTML=`<div class="matchbox"><div class="matchtop"><span>THE MOMENT <b>· ${c.club}</b></span><span id="shotcount">SHOT 1 / 3</span></div><div class="matchinstr" id="matchinstr">Time your strike. Stop the marker in the bright zone!</div><div class="meter" id="meter"><div class="sweetspot"></div><div class="needle" id="needle"></div></div><button class="shoot" id="shoot">⚽ &nbsp; SHOOT — TAP OR SPACE</button><div class="matchresult" id="matchresult">3 shots · make your moment count</div></div>`;$('#shoot').onclick=shoot;if(anim)cancelAnimationFrame(anim);animateNeedle()}
71: function animateNeedle(){if(game.phase!=='match')return;needle+=dir*1.35;if(needle>97){needle=97;dir=-1}if(needle<0){needle=0;dir=1}const el=$('#needle');if(el)el.style.left=needle+'%';anim=requestAnimationFrame(animateNeedle)}
72: function shoot(){if(game.phase!=='match')return;const accuracy=Math.abs(needle-50),goal=accuracy<13;game.shot++;if(goal){game.shotGoals++;game.stats.legacy=clamp(game.stats.legacy+3);$('#matchresult').textContent='GOAL! The net ripples. The crowd erupts!';beep(680)}else{$('#matchresult').textContent=accuracy<27?'SO CLOSE! The keeper gets fingertips to it.':'SAVED! The keeper read the shot.';beep(220)}$('#matchresult').style.color=goal?'var(--lime)':'var(--orange)';$('#shotcount').textContent=game.shot<3?`SHOT ${game.shot+1} / 3`:'FULL TIME';$('#shoot').disabled=true;$('#shoot').textContent=game.shot<3?'NEXT BALL →':'CONTINUE →';save();setTimeout(()=>{if(game.phase!=='match')return;if(game.shot>=3){game.stats.legacy=clamp(game.stats.legacy+game.shotGoals*2);game.phase='choice';game.chapter++;if(game.chapter>=chapters.length)game.phase='ending';save();render()}else{$('#shoot').disabled=false;$('#shoot').textContent='⚽  SHOOT — TAP OR SPACE';$('#matchresult').textContent=`${game.shotGoals} GOAL${game.shotGoals===1?'':'S'} · ${3-game.shot} SHOT${game.shot===2?'':'S'} LEFT`;$('#shotcount').textContent=`SHOT ${game.shot+1} / 3`;needle=0;dir=1}},850)}
73: function ending(){const s=game.stats,top=Object.keys(s).sort((a,b)=>s[b]-s[a])[0];let title,copy;if(top==='loyalty'){title='The captain';copy='The shirt changes, the teammates change, but your heart never leaves the team. From Madeira to the world, your greatest legacy is the people you lifted along the way.'}else if(top==='craft'){title='The artist';copy='A career built on relentless reinvention. Every touch, every run, every leap tells the story of a player who made the impossible look practiced.'}else if(top==='aura'){title='The phenomenon';copy='You made every stadium feel smaller and every moment feel yours. The lights followed you from Lisbon to every corner of the footballing world.'}else{title='The immortal';copy='You kept asking for one more moment—and delivered. The records are written in ink; the what-ifs are written in the hearts of everyone who watched.'}$('#content').innerHTML=`<div class="ending"><div class="eyebrow">YOUR STORY. YOUR LEGACY.</div><h2>${title}</h2><div class="score">${game.goals+game.shotGoals} CAREER GOALS · ${game.decisions.length} DECISIONS · ${game.shotGoals} MATCH MOMENTS</div><p>${copy} This is only one version of the story. What would you change next time?</p><button class="restart" id="restart">↺ PLAY A NEW CAREER</button></div>`;$('#restart').onclick=reset}
74: function updateSide(){const s=game.stats;$('#stats').innerHTML=Object.entries(labels).map(([k,v])=>`<div class="statrow"><span>${v.toUpperCase()}</span><div class="statbar"><div class="statfill" style="width:${s[k]}%"></div></div><span class="statnum">${s[k]}</span></div>`).join('');const top=Object.keys(s).sort((a,b)=>s[b]-s[a])[0];$('#rank').textContent=game.phase==='ending'?({craft:'PLAYMAKER',aura:'ICON',loyalty:'CAPTAIN',legacy:'LEGEND'}[top]):game.chapter>=5?'SUPERSTAR':game.chapter>=2?'RISING STAR':'ROOKIE';$('#timeline').innerHTML=chapters.map((c,i)=>`<div class="timeline-item ${i<game.chapter?'done':i===game.chapter&&game.phase!=='ending'?'active':''}"><span class="dot"></span><span>${c.club==='MANCHESTER UNITED'?'MAN U':c.club==='SPORTING CP'?'SPORTING':c.club==='REAL MADRID'?'REAL':c.club==='PORTUGAL'?'PORTUGAL':c.club==='AL NASSR'?'AL NASSR':c.club==='MADEIRA'?'MADEIRA':c.club}</span></div>`).join('')}
75: function reset(){if(confirm('Start a new career? Your current story will be replaced.')){localStorage.removeItem('extra-time-save');game=structuredClone(initial);selected=0;render()}}
76: $('#reset-btn').onclick=reset;$('#sound-btn').onclick=()=>{sound=!sound;$('#sound-btn').textContent=`♪ SOUND: ${sound?'ON':'OFF'}`};
77: function beep(freq){if(!sound)return;try{const a=new AudioContext(),o=a.createOscillator(),g=a.createGain();o.frequency.value=freq;o.type='square';g.gain.value=.04;o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+.12)}catch{}}
78: document.addEventListener('keydown',e=>{if(e.key===' '){if(game.phase==='match'){e.preventDefault();shoot()}return}if(game.phase==='choice'){if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();selected=selected?0:1;document.querySelectorAll('.choice').forEach((b,i)=>b.style.borderColor=i===selected?'var(--lime)':'');}if(e.key==='Enter'||e.key==='1'||e.key==='2'){const i=e.key==='2'?1:e.key==='1'?0:selected;choose(i)}}else if(game.phase==='intro'&&e.key==='Enter')$('#start')?.click()});
