 <div class="quest" id="quest"><b>YOUR QUEST</b> Speak with the village keeper to learn what has happened.</div><div><div class="sectitle">STAR SIGILS</div><div class="badges" id="badges"></div></div><div><div class="sectitle">FIELD NOTES</div><div class="progress" id="notes">Find your footing in Mythvale.</div></div><div class="sidefoot"><button id="sound">♪ SOUND: OFF</button><button id="savebtn">▣ SAVE</button><button id="reset">↺ NEW</button></div></aside></div>
 <div class="bottom"><span><b>WASD / ↑↓←→</b> MOVE · <b>E / SPACE</b> INTERACT · <b>ESC</b> MENU</span><span>YOUR PATH. YOUR LEGEND. <b>✦</b></span></div></main></div>
 <div id="modalRoot"></div><div class="toast" id="toast">GAME SAVED</div>
 <script>
+const SAVE_KEY='mythvale-lost-star-v1';
+const regions=[
+ {name:'Lumen Village',tag:'THE FIRST SPARK',title:'The valley of first light',color:['#83bb8a','#3e7954','#e5cc7d'],ambient:'Meadow'},
+ {name:'Verdant Wilds',tag:'THE GREENWOLD',title:'Where old roots remember',color:['#65a978','#315c47','#c3bd72'],ambient:'Forest'},
+ {name:'Cinderdeep',tag:'THE ASHEN ROAD',title:'A mountain that dreams in fire',color:['#ba8060','#694c45','#d3a268'],ambient:'Caves'},
+ {name:'Starfall Crown',tag:'ABOVE THE CLOUDS',title:'The sky keeps its promises',color:['#82b8c5','#4a7387','#d6ca8b'],ambient:'Ruins'}
+];
+const questNames=['Verdant Wilds','Cinderdeep','Starfall Crown'];
+const sigilNames=['Root Sigil','Ember Sigil','Sky Sigil'];
+const creatureTypes=[
+ {name:'Mosskin',icon:'❀',hp:30,atk:7,color:'#8ecb82'}, {name:'Cindercub',icon:'◆',hp:34,atk:8,color:'#ed9668'},
+ {name:'Cloudfinch',icon:'✦',hp:32,atk:8,color:'#8bcbd2'}, {name:'Murkling',icon:'●',hp:28,atk:6,color:'#b7a3d8'},
+ {name:'Thornback',icon:'❋',hp:42,atk:9,color:'#90b873'}, {name:'Glowmoth',icon:'✧',hp:26,atk:7,color:'#ead47b'}
+];
+const initial={started:false,zone:0,x:23,y:26,dir:'down',steps:0,day:1,hour:8,quest:0,shards:0,level:1,xp:0,hp:30,maxHp:30,atk:7,pet:0,items:{tonic:2,seed:3,star:0},sigils:[],fragments:[0,0,0],bosses:[false,false,false],caught:[],journal:0,encounters:0,seen:{},sound:false};
+let game=loadGame(),held={},lastMove=0,frame=0,toastTimer=0,audio=null,battle=null,modal=false;
+const $=s=>document.querySelector(s), canvas=$('#world'),ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;
+function loadGame(){try{const s=JSON.parse(localStorage.getItem(SAVE_KEY));return s&&Array.isArray(s.sigils)?{...structuredClone(initial),...s}:structuredClone(initial)}catch{return structuredClone(initial)}}
+function saveGame(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(game));$('#save').textContent='AUTOSAVED';toast('ADVENTURE SAVED')}catch{}}
+function toast(text){const t=$('#toast');t.textContent=text;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',1500)}
+function say(text){$('#message').innerHTML=text}
+function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
+function seed(x,y,z){let n=(x*374761393+y*668265263+z*1442695041)|0;n=(n^(n>>>13))*1274126177;return((n^(n>>>16))>>>0)/4294967295}
+const W=48,H=38,T=16;
+function isPath(zone,x,y){if(zone===0)return (y>=24&&y<=27)||(x>=19&&x<=26&&y>=10&&y<=28)||(x>=10&&x<=35&&y>=17&&y<=20)||(x>=35&&x<=47&&y>=17&&y<=20);
+ return (x>=20&&x<=24)||(y>=17&&y<=21)||(x>=23&&x<=45&&y>=18&&y<=20)||(x>=0&&x<=22&&y>=18&&y<=20)}
+function tile(zone,x,y){if(x<0||y<0||x>=W||y>=H)return 1;if(zone===0){if((x<2||y<2||x>45||y>35)&&!isPath(zone,x,y))return 1;if(x<4&&y>9&&y<29)return 1;if(y>31&&x<18)return 7}
+ else {if(x<2||y<2||x>45||y>35)return 1;if((x+y*2)%11===0&&seed(x,y,zone)<.42)return 5}
+ if(isPath(zone,x,y))return 2;
+ const r=seed(x,y,zone);
+ if(zone===0){if(r<.055)return 3;if(r>.91&&y>4&&y<32)return 4;if((x>6&&x<12&&y>7&&y<14)||(x>33&&x<40&&y>7&&y<13))return 6;return 0}
+ if(zone===1){if(r<.06)return 3;if(r>.59)return 6;if(r>.48)return 4;return 0}
+ if(zone===2){if(r<.1)return 7;if(r>.57)return 5;if(r>.48)return 4;return 0}
+ if(zone===3){if(r<.1)return 3;if(r>.57)return 5;if(r>.49)return 4;return 0}
+ return 0
+}
+const places={
+ npcs:[[{x:23,y:15,name:'Keeper Rowan',icon:'♟',role:'keeper'},{x:13,y:19,name:'Mira',icon:'♟',role:'healer'},{x:33,y:18,name:'Tavi',icon:'♟',role:'trader'}],[{x:22,y:12,name:'Fern',icon:'♟',role:'guide'},{x:29,y:23,name:'Old Forager',icon:'♟',role:'forager'}],[{x:21,y:11,name:'Pip',icon:'♟',role:'miner'},{x:31,y:25,name:'Magma Warden',icon:'♟',role:'boss'}],[{x:22,y:11,name:'Aeri',icon:'♟',role:'guide'},{x:31,y:25,name:'Astral Warden',icon:'♟',role:'boss'}]],
+ fragments:[[],[{x:9,y:8},{x:37,y:10},{x:10,y:29}],[{x:10,y:9},{x:38,y:27},{x:12,y:29}],[{x:10,y:9},{x:38,y:10},{x:10,y:29}]],
+ bosses:[[],{x:38,y:27},{x:31,y:25},{x:31,y:25}]
+};
+function blocked(z,x,y){const t=tile(z,x,y);if(t===1||t===6)return true;if(z===0&&((x>=7&&x<=10&&y>=8&&y<=11)||(x>=35&&x<=38&&y>=8&&y<=11)||(x>=27&&x<=30&&y>=8&&y<=11)))return true;return false}
+function completed(z){return z===0||game.bosses[z-1]}
+function enterZone(z,from){game.zone=z;if(from==='west'){game.x=44;game.y=19}else if(from==='east'){game.x=3;game.y=19}else{game.x=23;game.y=30}game.day+=z===0?0:0;game.hour=(game.hour+1)%24;say(`<b>${regions[z].name}.</b> ${regions[z].title}.`);saveGame();renderUI()}

