function enterZone(z,from){game.zone=z;if(from==='west'){game.x=44;game.y=19}else if(from==='east'){game.x=3;game.y=19}else{game.x=23;game.y=30}game.hour=(game.hour+1)%24;say(`<b>${regions[z].name}.</b> ${regions[z].title}.`);saveGame();renderUI()}
function showModal(html){modal=true;$('#modalRoot').innerHTML=`<div class="overlay"><div class="modal">${html}</div></div>`}
function hideModal(){modal=false;$('#modalRoot').innerHTML=''}
function talk(role,name){
 if(role==='keeper'){
  if(!game.started){game.started=true;game.quest=1;game.pet=0;game.hp=game.maxHp;game.journal++;say('<b>Keeper Rowan:</b> “The old star has broken into three sigils. Take this little Mosskin; it knows the safe paths. Find the three fragments in the Wilds, then face the Root Guardian.”');toast('MOSSKIN JOINED YOUR PARTY');saveGame();renderUI();return}
  if(game.quest>=4){say('<b>Keeper Rowan:</b> “The valley shines again, Wayfarer. There are still trails to wander and little mysteries to find.”');return}
  if(game.zone===0){say(`<b>Keeper Rowan:</b> “${questNames[game.quest-1]||'The wilds'} holds the next sigil. Gather three star fragments and meet its guardian.”`);return}
 }
 if(role==='healer'){game.hp=game.maxHp;say(`<b>Mira:</b> “A little rest fixes most things.” Your companion is fully healed.`);toast('PARTY RESTORED');saveGame();renderUI();return}
 if(role==='trader'){
  showModal(`<div class="eyebrow">VILLAGE TRADER · ${game.shards} STAR SHARDS</div><h2>“Useful things for a long road.”</h2><p>Tonics restore 18 HP in battle. Seeds restore 10 HP now. You earn shards from wild encounters.</p><div class="inventory"><div class="item">🧪 Tonic · 8 shards<br><button class="action" data-buy="tonic">BUY · 8</button></div><div class="item">🌱 Healing seed · 4 shards<br><button class="action" data-buy="seed">BUY · 4</button></div></div><div class="modalrow"><button class="action alt" data-close>LEAVE</button></div>`);document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buy(b.dataset.buy));$('[data-close]').onclick=hideModal;return
 }
 if(role==='guide'||role==='forager'||role==='miner'){
   const texts={guide:'The fragments glow like tiny stars. Their light is strongest near the old stone markers. Walk close and press E to gather one.',forager:'The tall grass hides shy creatures. They may become your friends if you offer a Star Seed when they are tired.',miner:'These tunnels are old as the mountain. The Cinder Guardian wakes only after the three fragments have been gathered.'};
   say(`<b>${name}:</b> “${texts[role]}”`);return
 }
 if(role==='boss'){startBattle(true);return}
 say(`<b>${name}:</b> “May the star light your way.”`)
}
function buy(item){const price=item==='tonic'?8:4;if(game.shards<price){toast('NOT ENOUGH STAR SHARDS');return}game.shards-=price;game.items[item]++;saveGame();talk('trader','Tavi')}
function interact(){if(modal)return;
 const z=game.zone;
 const np=places.npcs[z].find(n=>Math.abs(n.x-game.x)+Math.abs(n.y-game.y)<=2);
 if(np){talk(np.role,np.name);return}
 if(z>0&&z<=3){const frag=places.fragments[z].findIndex((p,i)=>!game.fragments[z-1]?.[i]&&Math.abs(p.x-game.x)+Math.abs(p.y-game.y)<=1);
  if(frag>=0){if(game.quest<z){say('<b>The fragment hums softly.</b> The village keeper mentioned a different path first.');return}game.fragments[z-1][frag]=true;game.shards+=2;game.journal++;say(`<b>Star fragment ${game.fragments[z-1].filter(Boolean).length}/3.</b> A warm light settles into your pack.`);toast('STAR FRAGMENT FOUND · +2 SHARDS');saveGame();renderUI();return}
  const b=places.bosses[z];if(b&&Math.abs(b.x-game.x)+Math.abs(b.y-game.y)<=2){if(game.fragments[z-1]?.filter(Boolean).length<3){say('<b>A sleeping guardian.</b> The three fragments are needed to wake it.');return}if(game.bosses[z-1]){say('<b>The guardian bows.</b> The sigil in your pack answers with a gentle light.');return}startBattle(true);return}
 }
 if(z===0&&(game.x>=44||game.y<=2)){say('<b>A winding trail leads east.</b> Take the road to Verdant Wilds?');showModal(`<div class="eyebrow">THE LONG ROAD</div><h2>Leave the village?</h2><p>Beyond the village waits the Verdant Wilds. Bring your companion, and remember that Mira can heal you back here.</p><div class="modalrow"><button class="action" id="travel">TRAVEL TO VERDANT WILDS</button><button class="action alt" data-close>NOT YET</button></div>`);$('#travel').onclick=()=>{hideModal();enterZone(1,'west')};$('[data-close]').onclick=hideModal;return}
 if(z===1&&game.x<=2){enterZone(0,'east');return}
 if(z===1&&game.x>=45){if(!game.bosses[0]){say('<b>The mountain pass is sealed.</b> Defeat the Root Guardian to open the way.');return}enterZone(2,'west');return}
 if(z===2&&game.x<=2){enterZone(1,'east');return}
 if(z===2&&game.x>=45){if(!game.bosses[1]){say('<b>A curtain of falling stone blocks the eastern road.</b> Find the Cinder Sigil.');return}enterZone(3,'west');return}
 if(z===3&&game.x<=2){enterZone(2,'east');return}
 say('<b>Nothing nearby.</b> Wander a little closer to a person, marker, or doorway.');
}
function startBattle(isBoss=false){const z=game.zone;const kind=isBoss?['Root Guardian','Cinder Warden','Astral Warden'][z-1]:null;let type=Math.floor(seed(game.steps,game.encounters,z)*creatureTypes.length);const base=creatureTypes[type];const level=Math.max(1,game.level+Math.floor(z*.7));battle={boss:isBoss,name:kind||base.name,icon:isBoss?['♜','♨','✦'][z-1]:base.icon,color:isBoss?'#dca876':base.color,max:(isBoss?34:base.hp)+level*5,hp:(isBoss?34:base.hp)+level*5,atk:(isBoss?8:base.atk)+level-1,level,turn:0,log:isBoss?`The ${kind} stirs. “Show me the courage of the valley.”`:`A wild ${base.name} appears!`,type};game.encounters++;if(isBoss)battle.max+=12,battle.hp+=12;renderBattle()}
function renderBattle(){if(!battle)return;const b=battle;showModal(`<div class="eyebrow">${b.boss?'GUARDIAN TRIAL':'WILD ENCOUNTER'} · ${regions[game.zone].name.toUpperCase()}</div><div class="battleinfo"><span>YOUR COMPANION · LV ${game.level}</span><span>${b.name} · LV ${b.level}</span></div><div style="display:flex;justify-content:space-between;align-items:center;margin:15px 4px 2px"><div class="orb" style="background:#426d59;border-color:#9ccb77">${creatureTypes[game.pet].icon}</div><div style="font-size:27px;color:${b.color}">${b.icon}</div></div><div class="battleinfo"><span>${game.hp}/${game.maxHp} HP</span><span>${b.hp}/${b.max} HP</span></div><div class="enemybar"><div class="enemyfill" style="width:${Math.max(0,b.hp/b.max*100)}%"></div></div><p id="battlelog">${b.log}</p><div class="battlebar"><button data-act="attack">⚔ STRIKE</button><button data-act="skill">✦ STAR BURST</button><button data-act="item">🧪 TONIC ×${game.items.tonic}</button><button data-act="seed">🌱 OFFER SEED ×${game.items.seed}</button><button data-act="run" ${b.boss?'disabled':''}>↗ RETREAT</button></div>`);
 document.querySelectorAll('[data-act]').forEach(el=>el.onclick=()=>battleAction(el.dataset.act));
}

