}
function begin(){if(!game.started){game.started=true;say('<b>Keeper Rowan waits in the village square.</b> Explore with WASD or the arrow keys, then press E beside people and shining stones.');saveGame();hideModal();renderUI();return}hideModal()}
function move(dir){if(!game.started||modal)return;const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[dir];if(!d)return;game.dir=dir;const nx=game.x+d[0],ny=game.y+d[1];if(blocked(game.zone,nx,ny))return;game.x=nx;game.y=ny;game.steps++;game.hour=(game.hour+1)%24;
 if(tile(game.zone,nx,ny)===4&&game.steps%5===0&&Math.random()<.25)startBattle(false);
 if(game.steps%12===0)saveGame();
}
function openMenu(){showModal(`<div class="eyebrow">TRAVELER’S SATCHEL</div><h2>Inventory & field journal</h2><p><b>Star shards:</b> ${game.shards} &nbsp; <b>Star Seeds:</b> ${game.items.seed} &nbsp; <b>Tonics:</b> ${game.items.tonic} &nbsp; <b>Star Apples:</b> ${game.items.star}</p><p><b>Discovered creatures:</b> ${game.caught.length?game.caught.map(i=>creatureTypes[i].name).join(', '):'None yet'}<br><b>Current region:</b> ${regions[game.zone].name}<br><b>Companion:</b> ${creatureTypes[game.pet].name} · level ${game.level}</p><div class="modalrow"><button class="action" id="menuSave">SAVE ADVENTURE</button><button class="action alt" id="menuClose">RETURN TO GAME</button></div>`);$('#menuSave').onclick=()=>{saveGame();hideModal()};$('#menuClose').onclick=hideModal}
function loop(now){if(now-lastMove>132){let dir=held.up?'up':held.down?'down':held.left?'left':held.right?'right':null;if(dir){move(dir);lastMove=now}}drawWorld();requestAnimationFrame(loop)}
document.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();if(key==='escape'){if(modal)hideModal();else openMenu();return}if(key==='enter'&&!game.started){begin();return}if(key==='e'||key===' '){if(!modal)interact();return}if(key==='m'){openMenu();return}if(key==='w'||key==='arrowup')held.up=true;if(key==='s'||key==='arrowdown')held.down=true;if(key==='a'||key==='arrowleft')held.left=true;if(key==='d'||key==='arrowright')held.right=true});
document.addEventListener('keyup',e=>{const key=e.key.toLowerCase();if(key==='w'||key==='arrowup')held.up=false;if(key==='s'||key==='arrowdown')held.down=false;if(key==='a'||key==='arrowleft')held.left=false;if(key==='d'||key==='arrowright')held.right=false});
window.addEventListener('blur',()=>held={});document.querySelectorAll('[data-dir]').forEach(b=>{const dir=b.dataset.dir;b.addEventListener('pointerdown',e=>{e.preventDefault();held[dir]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>held[dir]=false))});
$('#interact').onclick=interact;$('#menu').onclick=openMenu;$('#savebtn').onclick=saveGame;$('#sound').onclick=()=>{game.sound=!game.sound;$('#sound').textContent=`♪ SOUND: ${game.sound?'ON':'OFF'}`;saveGame()};$('#reset').onclick=()=>{if(confirm('Start a new adventure? Your current save will be replaced.')){localStorage.removeItem(SAVE_KEY);game=structuredClone(initial);held={};renderUI();say('<b>Welcome, Wayfarer.</b> Press Enter to begin your adventure.');intro()}};
function intro(){showModal(`<div class="eyebrow">A 16-BIT STORY RPG · 4 REGIONS · 3 SIGILS</div><h2>The Lost Star</h2><p>Long ago, one bright star watched over Mythvale. Now its three sigils are scattered across the valley, deep beneath the mountain, and high among the clouds.</p><p>Explore a hand-built world, meet its people, befriend curious creatures, uncover secrets, and challenge ancient guardians. Your journey saves automatically in this browser.</p><div class="modalrow"><button class="action" id="startGame">${game.started?'CONTINUE ADVENTURE':'BEGIN ADVENTURE'}</button><button class="action alt" id="howto">HOW TO PLAY</button></div>`);$('#startGame').onclick=begin;$('#howto').onclick=()=>showModal(`<div class="eyebrow">FIELD GUIDE</div><h2>How to play</h2><p><b>Move:</b> WASD, arrow keys, or the on-screen D-pad.<br><b>Interact:</b> E or Space when close to a person, fragment, or road.<br><b>Battle:</b> Strike or use Star Burst. Tonics heal; weakened wild creatures may join your journal with a Star Seed. Guardians cannot be captured.<br><b>Quest:</b> Speak to Keeper Rowan, collect three fragments in each region, then find its guardian. Mira heals you in the village; Tavi sells supplies.</p><div class="modalrow"><button class="action" id="guideBack">GOT IT</button></div>`);$('#guideBack').onclick=intro}
renderUI();if(game.started){say('<b>Welcome back, Wayfarer.</b> Your last journey was saved.');}else intro();requestAnimationFrame(loop);
</script>
</body>
</html>

